###############################################################################
# common_setup.tcl -- PrimeTime STA flow variable hub
#
# 所有变量都提供默认值(default)。它们通过 pt_shell 的 -x 选项(或 source 之前的
# set 命令)即可被外部覆盖，从而实现"按 corner / mode 传参适配"。
#
# 变量命名与 feint 参考流(/apps/imctf/cad/script/digital_flow/feint)保持一致。
# 核心规则：`if {![info exists VAR]}` 保证默认值只在未定义时生效，
# 即 -x 传入的同名变量优先级最高。
###############################################################################

###################################################################
# Flow directory layout
###################################################################
if {![info exists ROOT_DIR]}     { set ROOT_DIR     "." }
if {![info exists SCR_DIR]}      { set SCR_DIR      "$ROOT_DIR/scr" }
if {![info exists SETUP_DIR]}    { set SETUP_DIR    "$ROOT_DIR/setup" }
if {![info exists DATA_DIR]}     { set DATA_DIR     "$ROOT_DIR/data" }

# 输出件层次(用户已生成的层次)
if {![info exists LOG_DIR]}      { set LOG_DIR      "$ROOT_DIR/log" }
if {![info exists RPT_DIR]}      { set RPT_DIR      "$ROOT_DIR/rpt" }
if {![info exists SDC_DIR]}      { set SDC_DIR      "$ROOT_DIR/sdc" }
if {![info exists SESSION_DIR]}  { set SESSION_DIR  "$ROOT_DIR/session" }

###################################################################
# Design / Corner / Mode
###################################################################
if {![info exists DESIGN]}       { set DESIGN       "demo" }
if {![info exists DESIGN_NAME]}  { set DESIGN_NAME  "$DESIGN" }
if {![info exists CORNER]}       { set CORNER       "tt0p8v25c" }
if {![info exists PT_CORNER]}    { set PT_CORNER    "$CORNER" }
if {![info exists MODE]}         { set MODE         "func" }
if {![info exists PT_MODE]}      { set PT_MODE      "$MODE" }

###################################################################
# Tool selection (module / version)
###################################################################
if {![info exists PT_VERSION]}   { set PT_VERSION   "U-2022.12-SP5" }
if {![info exists PT_ROOT]}      { set PT_ROOT      "/apps/synopsys/primetime" }

###################################################################
# Library inputs (子模块 lib 输入件)
###################################################################
if {![info exists ANALYSIS_LIBRARY_FILES]}     { set ANALYSIS_LIBRARY_FILES    "" }
if {![info exists ADDITIONAL_LINK_LIB_FILES]}  { set ADDITIONAL_LINK_LIB_FILES "" }
if {![info exists ADDITIONAL_SEARCH_PATH]}     { set ADDITIONAL_SEARCH_PATH    "" }

###################################################################
# Netlist / Constraint / Parasitic inputs
###################################################################
if {![info exists NETLIST_FILES]}    { set NETLIST_FILES    "" }
if {![info exists CONSTRAINT_FILES]} { set CONSTRAINT_FILES "" }
if {![info exists PARASITIC_FILES]}  { set PARASITIC_FILES  "" }
if {![info exists PARASITIC_PATHS]}  { set PARASITIC_PATHS  "" }
if {![info exists POCVM_FILES]}      { set POCVM_FILES      "" }

###################################################################
# Session / naming
###################################################################
if {![info exists SESSION_NAME]} { set SESSION_NAME "${DESIGN_NAME}_${CORNER}_${MODE}_ss" }

###################################################################
# 通用工具：按扩展名在指定目录(含一级子目录，如 data/lib)中查找文件。
# 用于 demo design 未显式指定 lib/netlist/sdc/spef 时的自动发现。
###################################################################
proc sta_find_files {dir patterns} {
    set out {}
    foreach pat $patterns {
        foreach m [glob -nocomplain -types f [file join $dir $pat]] {
            lappend out $m
        }
        foreach m [glob -nocomplain -types f [file join $dir * $pat]] {
            lappend out $m
        }
    }
    return [lsort -unique $out]
}

###############################################################################
# 2_read_lib.tcl -- 读入子模块 lib 输入件，配置 target/link library
# 支持 .lib(读入并编译) 与 .db(直接用于 target/link) 两种输入。
###############################################################################
puts "RM-Info: 2_read_lib: reading library inputs ..."

# 若 -x 未显式给库，则自动在 data/(含 data/lib/) 中发现
set _libs $ANALYSIS_LIBRARY_FILES
if {[string length $_libs] == 0} {
    set _libs [sta_find_files $DATA_DIR {*.lib *.db}]
}
puts "RM-Info: 2_read_lib: library files = $_libs"

set _target_libs {}
foreach _l $_libs {
    # 库所在目录加入 search_path，便于 db 解析子模块引用
    lappend search_path [file dirname $_l]
    set _ext [string tolower [file extension $_l]]
    if {$_ext eq ".lib"} {
        set _lib_obj [read_lib $_l]
        foreach_in_collection _lb $_lib_obj {
            lappend _target_libs [get_object_name $_lb]
        }
    } else {
        lappend _target_libs $_l
    }
}

set target_library [lsort -unique $_target_libs]
set link_path      "* $target_library $ADDITIONAL_LINK_LIB_FILES"

puts "RM-Info: 2_read_lib: target_library = $target_library"
puts "RM-Info: 2_read_lib: link_path      = $link_path"

###############################################################################
# 3_read_design.tcl -- 读入网表(netlist) 并 link 顶层设计
###############################################################################
puts "RM-Info: 3_read_design: reading netlist ..."

set _netlists $NETLIST_FILES
if {[string length $_netlists] == 0} {
    set _netlists [sta_find_files $DATA_DIR {*.v *.vg *.v.gz *.vg.gz}]
}
if {[llength $_netlists] == 0} {
    puts "RM-Error: 3_read_design: no netlist found (NETLIST_FILES empty and data/ empty)."
    if {$sh_continue_on_error} {
        puts "RM-Info:  3_read_design: skipping design read."
    } else {
        exit 1
    }
} else {
    puts "RM-Info: 3_read_design: netlist files = $_netlists"
    foreach _n $_netlists {
        puts "RM-Info: 3_read_design: read_verilog $_n"
        read_verilog $_n
    }

    if {[string length $DESIGN_NAME] == 0} {
        set DESIGN_NAME [get_object_name [current_design]]
    }
    current_design $DESIGN_NAME
    link

    puts "RM-Info: 3_read_design: current_design = [get_object_name [current_design]]"
}

###############################################################################
# 4_read_constraint.tcl -- 读入时序约束(.sdc / .tcl)
###############################################################################
puts "RM-Info: 4_read_constraint: reading constraints ..."

set _sdcs $CONSTRAINT_FILES
if {[string length $_sdcs] == 0} {
    set _sdcs [sta_find_files $DATA_DIR {*.sdc *.tcl}]
}
puts "RM-Info: 4_read_constraint: constraint files = $_sdcs"

foreach _c $_sdcs {
    set _ext [string tolower [file extension $_c]]
    if {$_ext eq ".sdc"} {
        puts "RM-Info: 4_read_constraint: read_sdc -echo $_c"
        read_sdc -echo $_c
    } else {
        puts "RM-Info: 4_read_constraint: source -echo $_c"
        source -echo $_c
    }
}

###############################################################################
# 5_read_parasitic.tcl -- 读入寄生参数(SPEF) 反标
###############################################################################
puts "RM-Info: 5_read_parasitic: reading parasitics ..."

set _spefs $PARASITIC_FILES
set _paths $PARASITIC_PATHS

if {[string length $_spefs] == 0} {
    set _spefs [sta_find_files $DATA_DIR {*.spef *.spef.gz *.spf}]
}

if {[llength $_spefs] > 0} {
    puts "RM-Info: 5_read_parasitic: parasitic files = $_spefs"
    # 推荐顺序: 先 block spef, 后 top spef
    if {[llength $_paths] == [llength $_spefs]} {
        foreach _p $_paths _f $_spefs {
            if {[string equal $_p $DESIGN_NAME]} {
                read_parasitics $_f
            } else {
                read_parasitics -path $_p $_f
            }
        }
    } else {
        foreach _f $_spefs {
            puts "RM-Info: 5_read_parasitic: read_parasitics $_f"
            read_parasitics $_f
        }
    }
} else {
    puts "RM-Info: 5_read_parasitic: no parasitic files found; skipping back-annotation."
}

